 "content": "from math import gcd
from functools import reduce

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    rs = [r for r, c, v in marks]
    cs = [c for r, c, v in marks]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    pattern = [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
    # The color key is turned clockwise, then each key cell colors a same-sized
    # square tile in the large 8-shaped silhouette.
    pattern = [list(row) for row in zip(*pattern[::-1])]

    runs = []
    for r in range(h):
        n = 0
        for c in range(w + 1):
            if c < w and grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
    for c in range(w):
        n = 0
        for r in range(h + 1):
            if r < h and grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
    tile = reduce(gcd, runs)
    r8 = min(r for r in range(h) for c in range(w) if grid[r][c] == 8)
    c8 = min(c for c in range(w) if any(grid[r][c] == 8 for r in range(h)))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8:
                tr, tc = (r - r8) // tile, (c - c8) // tile
                if 0 <= tr < len(pattern) and 0 <= tc < len(pattern[0]):
                    out[r][c] = pattern[tr][tc]
    return out
